class AuditedPayments final : public PaymentService {          // same interface
public:
    AuditedPayments(PaymentService& inner, AuditSink& sink) : inner_(inner), sink_(sink) {}
    Receipt pay(const Payment& p) override {
        sink_.record(whoami(), "pay", p.id(), Outcome::attempt);
        try { auto r = inner_.pay(p); sink_.record(whoami(), "pay", p.id(), Outcome::ok); return r; }
        catch (...) { sink_.record(whoami(), "pay", p.id(), Outcome::failed); throw; }
    }
private:
    PaymentService& inner_;
    AuditSink&     sink_;
};
